  ["89da26d4917f0b80"] = { "儀式の間は物音を立てるな。一つの過ちが我らの破滅を招きかねない……", "." },
  ["89df9e8de9968157"] = { "Old TownのBarracksか、Pig and Whistle Tavernのあたりを探してみな。酒場へ行くなら、上等なビールをぜひ味わってくれよ。ドワーフのエールなんか目じゃないぜ、ほんとに。", "." },
  ["89e0bdcca491cf48"] = { "恐れることはない。Night Watchがすぐにこの地から汚れた穢れを取り除く。", "." },
  ["89e52da8df5c6eeb"] = { "二人の恋人が倒れた場所に、一本の木が花を咲かせた。エルフはそれをheartswoodと呼ぶ。きっと君の目的に役立つだろう。", "." },
  ["89ea302d1d1395f4"] = { "<Omarionが小声で何かをぼやく。>\n\nだがもちろん、手を貸してやろう、我が子よ。それが私の死に際の願い……最後の望みだ。さあ、この手引書を受け取ってくれ。そのページに記された情報は、私の惨めな人生の過去30年あまりで知り、学んだことのすべてをまとめたものだ。この手引書を、今頃Light's Hope Chapelで太った尻を据えて座っているであろう、あの役立たずの弟子に渡してくれ。", "." },
  ["89eb0bbc0658b3e0"] = { "Teldrassilを覆うひんやりとした草も寝床として申し分ないと思いますが、Craftsman's Terraceの宿屋でSaelienneが用意しているベッドは、贅沢を好む方にもぴったりですよ。", "." },
